#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TurnDiffState {
    pub turn_id: String,
    pub unified_diff: String,
    pub truncated: bool,
}

impl TimelineState {
    fn rebuild_item_indices(&mut self) {
        let mut item_indices = HashMap::with_capacity(self.items.len());
        for (index, item) in self.items.iter().enumerate() {
            item_indices.entry(item.id.clone()).or_insert(index);
        }
        self.item_indices = item_indices;
    }

    fn item_index(&self, item_id: &str) -> Option<usize> {
        self.item_indices.get(item_id).copied()
    }

    fn trim_items(&mut self, limit: usize) -> bool {
        let overflow = self.items.len().saturating_sub(limit);
        if overflow == 0 {
            return false;
        }
        self.items.drain(..overflow);
        self.rebuild_item_indices();
        true
    }

    #[must_use]
    pub fn items(&self) -> &[TimelineItem] {
        &self.items
    }

    #[must_use]
    pub fn output_artifacts(&self) -> Vec<OutputArtifact> {
        let mut seen = HashSet::new();
        let mut artifacts = Vec::new();
        for item in self.items.iter().rev() {
            let active_turn = self.active_turn_id.as_deref() == Some(item.turn_id.as_str());
            for artifact in item.output_artifacts.iter().rev() {
                if active_turn && artifact.kind != OutputArtifactKind::GeneratedImage {
                    continue;
                }
                let mut key = artifact.path.to_string_lossy().replace('\\', "/");
                if cfg!(windows) {
                    key.make_ascii_lowercase();
                }
                if key.is_empty() || !seen.insert(key) {
                    continue;
                }
                artifacts.push(artifact.clone());
                if artifacts.len() == MAX_OUTPUT_ARTIFACTS {
                    return artifacts;
                }
            }
        }
        artifacts
    }
}

