#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PullRequestMutationKind {
    Comment,
    Approve,
    ReviewComment,
    RequestChanges,
    MarkDraft,
    MarkReady,
    EditTitle,
    EditDescription,
    Merge,
    Squash,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PullRequestMutation {
    Comment {
        body: String,
    },
    Review {
        event: PullRequestReviewEvent,
        body: String,
    },
    SetReviewState {
        state: PullRequestReviewState,
    },
    EditTitle {
        title: String,
    },
    EditDescription {
        body: String,
    },
    Merge {
        method: PullRequestMergeMethod,
    },
}

impl PullRequestMutation {
    const fn kind(&self) -> PullRequestMutationKind {
        match self {
            Self::Comment { .. } => PullRequestMutationKind::Comment,
            Self::Review {
                event: PullRequestReviewEvent::Approve,
                ..
            } => PullRequestMutationKind::Approve,
            Self::Review {
                event: PullRequestReviewEvent::Comment,
                ..
            } => PullRequestMutationKind::ReviewComment,
            Self::Review {
                event: PullRequestReviewEvent::RequestChanges,
                ..
            } => PullRequestMutationKind::RequestChanges,
            Self::SetReviewState {
                state: PullRequestReviewState::Draft,
            } => PullRequestMutationKind::MarkDraft,
            Self::SetReviewState {
                state: PullRequestReviewState::Ready,
            } => PullRequestMutationKind::MarkReady,
            Self::EditTitle { .. } => PullRequestMutationKind::EditTitle,
            Self::EditDescription { .. } => PullRequestMutationKind::EditDescription,
            Self::Merge {
                method: PullRequestMergeMethod::Merge,
            } => PullRequestMutationKind::Merge,
            Self::Merge {
                method: PullRequestMergeMethod::Squash,
            } => PullRequestMutationKind::Squash,
        }
    }
}

