    #[test]
    fn active_turn_submission_steers_and_stop_is_deduplicated() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("t1")));
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::ComposerChanged("focus on the failing test".to_owned()),
        );

        assert_eq!(
            reduce(&mut state, Action::SubmitComposer),
            [Effect::SteerTurn {
                task_id: "t1".to_owned(),
                expected_turn_id: "turn-1".to_owned(),
                text: "focus on the failing test".to_owned(),
                attachments: Vec::new(),
            }]
        );
        assert_eq!(
            reduce(&mut state, Action::InterruptActiveTurn),
            [Effect::InterruptTurn {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
            }]
        );
        assert!(reduce(&mut state, Action::InterruptActiveTurn).is_empty());

        reduce(
            &mut state,
            Action::TurnInterruptFailed {
                task_id: "t1".to_owned(),
                message: "failed to stop turn".to_owned(),
            },
        );
        assert!(
            state
                .timelines
                .get("t1")
                .is_some_and(|timeline| !timeline.interrupt_pending)
        );
    }

    #[test]
    fn stale_terminal_turn_events_do_not_override_a_new_active_turn() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("t1")));
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "t1".to_owned(),
                turn_id: "turn-old".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "t1".to_owned(),
                turn_id: "turn-current".to_owned(),
            },
        );
        reduce(&mut state, Action::InterruptActiveTurn);

        assert!(
            reduce(
                &mut state,
                Action::TurnCompleted {
                    task_id: "t1".to_owned(),
                    turn_id: "turn-old".to_owned(),
                    completed: true,
                    failed: false,
                },
            )
            .is_empty()
        );
        assert!(
            reduce(
                &mut state,
                Action::TurnInterrupted {
                    task_id: "t1".to_owned(),
                    turn_id: "turn-old".to_owned(),
                },
            )
            .is_empty()
        );
        assert_eq!(
            state.timelines["t1"].active_turn_id.as_deref(),
            Some("turn-current")
        );
        assert!(state.timelines["t1"].interrupt_pending);
        assert_eq!(state.tasks[0].status, TaskRunStatus::Running);
        assert_eq!(state.status_message, None);
    }

    #[test]
    fn only_exact_successful_background_turns_show_a_completion_banner() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("selected")));
        reduce(&mut state, Action::TaskCreated(task("background")));
        reduce(&mut state, Action::SelectTask("selected".to_owned()));

        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "background".to_owned(),
                turn_id: "background-success".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "background".to_owned(),
                turn_id: "background-success".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert_eq!(
            state.background_completion_task_id.as_deref(),
            Some("background")
        );
        assert_eq!(state.status_message, None);

        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "background".to_owned(),
                turn_id: "background-second-success".to_owned(),
            },
        );
        assert_eq!(state.background_completion_task_id, None);
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "background".to_owned(),
                turn_id: "background-second-success".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert_eq!(
            state.background_completion_task_id.as_deref(),
            Some("background")
        );

        reduce(&mut state, Action::SetStatus("Unrelated status".to_owned()));
        reduce(&mut state, Action::ClearStatus);
        assert_eq!(
            state.background_completion_task_id.as_deref(),
            Some("background")
        );
        reduce(&mut state, Action::DismissBackgroundCompletion);
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "background".to_owned(),
                turn_id: "background-success".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert_eq!(state.background_completion_task_id, None);
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "background".to_owned(),
                turn_id: "background-unknown".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "background".to_owned(),
                turn_id: "background-unknown".to_owned(),
                completed: false,
                failed: false,
            },
        );
        assert_eq!(state.background_completion_task_id, None);

        let oversized_task_id = "x".repeat(MAX_PINNED_TASK_ID_BYTES + 1);
        reduce(&mut state, Action::TaskCreated(task(&oversized_task_id)));
        reduce(&mut state, Action::SelectTask("selected".to_owned()));
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: oversized_task_id.clone(),
                turn_id: "oversized-success".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: oversized_task_id,
                turn_id: "oversized-success".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert_eq!(state.background_completion_task_id, None);

        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "selected".to_owned(),
                turn_id: "selected-success".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "selected".to_owned(),
                turn_id: "selected-success".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert_eq!(state.background_completion_task_id, None);

        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "background".to_owned(),
                turn_id: "background-failed".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "background".to_owned(),
                turn_id: "background-failed".to_owned(),
                completed: false,
                failed: true,
            },
        );
        assert_eq!(state.background_completion_task_id, None);

        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "background".to_owned(),
                turn_id: "background-interrupted".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::TurnInterrupted {
                task_id: "background".to_owned(),
                turn_id: "background-interrupted".to_owned(),
            },
        );
        assert_eq!(state.background_completion_task_id, None);
    }

    #[test]
    fn background_completion_open_and_dismiss_are_independent_of_status() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("selected")));
        reduce(&mut state, Action::TaskCreated(task("background")));
        reduce(&mut state, Action::SelectTask("selected".to_owned()));

        state.background_completion_task_id = Some("background".to_owned());
        state.status_message = Some("Unrelated status".to_owned());
        reduce(&mut state, Action::DismissBackgroundCompletion);
        assert_eq!(state.background_completion_task_id, None);
        assert_eq!(state.status_message.as_deref(), Some("Unrelated status"));

        state.background_completion_task_id = Some("background".to_owned());
        reduce(&mut state, Action::OpenBackgroundCompletion);
        assert_eq!(state.background_completion_task_id, None);
        assert_eq!(state.selected_task_id.as_deref(), Some("background"));

        reduce(&mut state, Action::SelectTask("selected".to_owned()));
        state.background_completion_task_id = Some("background".to_owned());
        reduce(&mut state, Action::SelectTask("background".to_owned()));
        assert_eq!(state.background_completion_task_id, None);

        reduce(&mut state, Action::SelectTask("selected".to_owned()));
        state.background_completion_task_id = Some("missing".to_owned());
        reduce(&mut state, Action::OpenBackgroundCompletion);
        assert_eq!(state.background_completion_task_id, None);
        assert_eq!(state.selected_task_id.as_deref(), Some("selected"));
    }

