    #[test]
    fn a_selected_folder_becomes_the_explicit_workspace_for_the_next_chat() {
        let mut state = AppState::default();
        let workspace = if cfg!(windows) {
            PathBuf::from(r"C:\repo")
        } else {
            PathBuf::from("/repo")
        };

        let effects = reduce(&mut state, Action::SelectWorkspace(workspace.clone()));

        assert_eq!(state.route, MainRoute::Tasks);
        assert_eq!(state.new_chat_cwd.as_ref(), Some(&workspace));
        assert!(effects.contains(&Effect::RememberWorkspace {
            path: workspace.clone()
        }));
        assert!(effects.contains(&Effect::PersistUiState {
            route: MainRoute::Tasks,
            inspector: InspectorPane::Hidden,
        }));

        reduce(&mut state, Action::ComposerChanged("start here".to_owned()));
        assert!(matches!(
            reduce(&mut state, Action::SubmitComposer).as_slice(),
            [Effect::CreateTask {
                cwd: Some(path),
                initial_message,
                ..
            }] if path == &workspace && initial_message == "start here"
        ));

        let prior_workspace = state.new_chat_cwd.clone();
        assert!(
            reduce(
                &mut state,
                Action::SelectWorkspace(PathBuf::from("relative"))
            )
            .is_empty()
        );
        assert_eq!(state.new_chat_cwd, prior_workspace);
    }

    #[test]
    fn local_projects_load_and_support_add_rename_pin_open_and_remove() {
        let first = if cfg!(windows) {
            PathBuf::from(r"C:\projects\first")
        } else {
            PathBuf::from("/projects/first")
        };
        let second = if cfg!(windows) {
            PathBuf::from(r"C:\projects\second")
        } else {
            PathBuf::from("/projects/second")
        };
        let mut state = AppState::default();
        reduce(
            &mut state,
            Action::LocalProjectsLoaded(vec![
                LocalProjectSummary {
                    path: first.clone(),
                    name: String::new(),
                    pinned: false,
                    last_opened_at: 1,
                },
                LocalProjectSummary {
                    path: second.clone(),
                    name: "Second".to_owned(),
                    pinned: true,
                    last_opened_at: 2,
                },
                LocalProjectSummary {
                    path: PathBuf::from("relative"),
                    name: "Ignored".to_owned(),
                    pinned: false,
                    last_opened_at: 3,
                },
            ]),
        );
        assert_eq!(state.local_projects.len(), 2);
        assert_eq!(state.local_projects[0].path, second);
        assert_eq!(state.local_projects[1].name, "first");

        let select_effects = reduce(&mut state, Action::SelectWorkspace(first.clone()));
        assert!(select_effects.contains(&Effect::RememberWorkspace {
            path: first.clone(),
        }));
        assert_eq!(state.new_chat_cwd.as_ref(), Some(&first));

        assert_eq!(
            reduce(
                &mut state,
                Action::RenameLocalProject {
                    path: first.clone(),
                    name: "  Native client  ".to_owned(),
                },
            ),
            [Effect::RenameLocalProject {
                path: first.clone(),
                name: "Native client".to_owned(),
            }]
        );
        assert_eq!(
            state
                .local_projects
                .iter()
                .find(|project| project.path == first)
                .map(|project| project.name.as_str()),
            Some("Native client")
        );

        assert_eq!(
            reduce(&mut state, Action::ToggleLocalProjectPinned(first.clone())),
            [Effect::SetLocalProjectPinned {
                path: first.clone(),
                pinned: true,
            }]
        );
        assert_eq!(
            reduce(&mut state, Action::OpenLocalProject(first.clone())),
            [Effect::OpenWorkspacePath {
                root: first.clone(),
                path: first.clone(),
            }]
        );

        let mut chat = task("chat");
        chat.cwd = first.clone();
        state.tasks.push(chat);
        let remove_effects = reduce(&mut state, Action::RemoveLocalProject(first.clone()));
        assert!(remove_effects.contains(&Effect::RemoveLocalProject {
            path: first.clone(),
        }));
        assert!(remove_effects.contains(&Effect::RefreshSkills {
            cwds: Vec::new(),
            force_reload: false,
        }));
        assert_eq!(state.tasks.len(), 1);
        assert!(state.new_chat_cwd.is_none());
        assert!(
            state
                .local_projects
                .iter()
                .all(|project| project.path != first)
        );
    }

    #[test]
    fn project_picker_changes_the_new_chat_workspace_without_clearing_the_draft() {
        let mut state = AppState::default();
        let workspace = if cfg!(windows) {
            PathBuf::from(r"C:\repo")
        } else {
            PathBuf::from("/repo")
        };
        let attachment = ComposerAttachment {
            path: workspace.join("AGENTS.md"),
            name: "AGENTS.md".to_owned(),
            kind: ComposerAttachmentKind::Mention,
        };
        state.composer = "keep this draft".to_owned();
        state.composer_attachments.push(attachment.clone());
        state.composer_controls.plan_mode = true;

        let effects = reduce(
            &mut state,
            Action::SelectComposerWorkspace(workspace.clone()),
        );

        assert_eq!(state.new_chat_cwd.as_ref(), Some(&workspace));
        assert_eq!(state.composer, "keep this draft");
        assert_eq!(state.composer_attachments, [attachment]);
        assert!(state.composer_controls.plan_mode);
        assert!(effects.contains(&Effect::RefreshSkills {
            cwds: vec![workspace.clone()],
            force_reload: false,
        }));
        assert!(effects.contains(&Effect::RefreshComposerPlugins {
            generation: 1,
            cwds: vec![workspace.clone()],
            force_refetch: false,
        }));
        assert!(effects.contains(&Effect::RememberWorkspace {
            path: workspace.clone(),
        }));

        state.selected_task_id = Some("thread-1".to_owned());
        let prior_workspace = state.new_chat_cwd.clone();
        assert!(
            reduce(
                &mut state,
                Action::SelectComposerWorkspace(if cfg!(windows) {
                    PathBuf::from(r"D:\other")
                } else {
                    PathBuf::from("/other")
                }),
            )
            .is_empty()
        );
        assert_eq!(state.new_chat_cwd, prior_workspace);
    }

