    #[test]
    fn safety_buffering_retry_tracks_only_the_active_submitted_turn() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("t1")));
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
            },
        );
        let submission = RetryableTurnSubmission {
            messages: vec![RetryableUserMessage {
                text: "Inspect the failure".to_owned(),
                attachments: Vec::new(),
            }],
            model: Some("gpt-5.6-sol".to_owned()),
            effort: Some("high".to_owned()),
            service_tier: Some("priority".to_owned()),
            permissions: Some(":workspace".to_owned()),
            approval_policy: Some("on-request".to_owned()),
            approvals_reviewer: Some(ApprovalsReviewer::AutoReview),
            plan_mode: false,
            personality: Personality::Pragmatic,
        };
        reduce(
            &mut state,
            Action::TurnSubmissionRecorded {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                submission: submission.clone(),
            },
        );
        reduce(
            &mut state,
            Action::SafetyBufferingUpdated {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                show_buffering_ui: true,
                faster_model: Some("gpt-5.6-terra".to_owned()),
            },
        );
        assert!(
            state.timelines["t1"]
                .safety_buffering
                .as_ref()
                .is_some_and(|buffering| buffering.retry_available && !buffering.dismissed)
        );

        reduce(
            &mut state,
            Action::DismissSafetyBuffering {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::SafetyBufferingUpdated {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                show_buffering_ui: true,
                faster_model: Some("gpt-5.6-terra".to_owned()),
            },
        );
        assert!(
            state.timelines["t1"]
                .safety_buffering
                .as_ref()
                .is_some_and(|buffering| buffering.dismissed)
        );

        reduce(
            &mut state,
            Action::SafetyBufferingUpdated {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                show_buffering_ui: true,
                faster_model: None,
            },
        );
        assert!(
            state.timelines["t1"]
                .safety_buffering
                .as_ref()
                .is_some_and(|buffering| !buffering.retry_available && !buffering.dismissed)
        );
        reduce(
            &mut state,
            Action::SafetyBufferingUpdated {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                show_buffering_ui: true,
                faster_model: Some("gpt-5.6-terra".to_owned()),
            },
        );
        assert_eq!(
            reduce(
                &mut state,
                Action::RetrySafetyBufferedTurn {
                    task_id: "t1".to_owned(),
                    turn_id: "turn-1".to_owned(),
                },
            ),
            [Effect::RetrySafetyBufferedTurn {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                faster_model: "gpt-5.6-terra".to_owned(),
                submission,
            }]
        );
        assert!(
            state.timelines["t1"]
                .safety_buffering
                .as_ref()
                .is_some_and(|buffering| buffering.retry_pending && buffering.dismissed)
        );

        reduce(
            &mut state,
            Action::SafetyBufferedRetryFailed {
                source_task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                restore_task_id: None,
                prompt: None,
                message: "Could not retry.".to_owned(),
            },
        );
        assert!(
            state.timelines["t1"]
                .safety_buffering
                .as_ref()
                .is_some_and(|buffering| !buffering.retry_pending && !buffering.dismissed)
        );
        reduce(
            &mut state,
            Action::TimelineDelta {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                item_id: "answer-1".to_owned(),
                kind: TimelineKind::Agent,
                delta: "Ready".to_owned(),
            },
        );
        assert!(state.timelines["t1"].safety_buffering.is_none());
        assert!(state.timelines["t1"].retryable_turn.is_none());
        reduce(
            &mut state,
            Action::SafetyBufferingUpdated {
                task_id: "t1".to_owned(),
                turn_id: "turn-1".to_owned(),
                show_buffering_ui: true,
                faster_model: Some("gpt-5.6-terra".to_owned()),
            },
        );
        assert!(state.timelines["t1"].safety_buffering.is_none());
    }

    #[test]
    fn loaded_threads_are_prioritized_and_resumed_once_after_reconnect() {
        let mut background = task("background");
        background.status = TaskRunStatus::Running;
        let mut selected = task("selected");
        selected.status = TaskRunStatus::WaitingForApproval;
        let mut state = AppState {
            tasks: vec![task("older"), task("selected")],
            selected_task_id: Some("selected".to_owned()),
            ..AppState::default()
        };

        assert_eq!(
            reduce(
                &mut state,
                Action::LoadedTasksRestored {
                    tasks: vec![background, selected],
                    truncated: true,
                },
            ),
            [Effect::ResumeTask {
                task_id: "background".to_owned(),
                generation: 1,
            }]
        );
        assert_eq!(
            state
                .tasks
                .iter()
                .take(2)
                .map(|task| task.id.as_str())
                .collect::<Vec<_>>(),
            ["background", "selected"]
        );
        assert_eq!(state.tasks[0].status, TaskRunStatus::Running);
        assert_eq!(
            state.status_message.as_deref(),
            Some("Restored the first 20 loaded chats.")
        );
    }

    #[test]
    fn goal_mutations_are_validated_and_wait_for_app_server_confirmation() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("t1")));

        assert_eq!(
            reduce(
                &mut state,
                Action::SetGoal {
                    objective: "  Reach native parity  ".to_owned(),
                    token_budget: Some(Some(50_000)),
                }
            ),
            [Effect::SetGoal {
                task_id: "t1".to_owned(),
                objective: Some("Reach native parity".to_owned()),
                status: Some(ThreadGoalStatus::Active),
                token_budget: Some(Some(50_000)),
            }]
        );
        assert_eq!(
            state.goals.get("t1").map(|goal| goal.status),
            Some(LoadStatus::Loading)
        );

        reduce(
            &mut state,
            Action::GoalUpdated(ThreadGoal {
                task_id: "t1".to_owned(),
                objective: "Reach native parity".to_owned(),
                status: ThreadGoalStatus::Active,
                tokens_used: 1_000,
                token_budget: Some(50_000),
                time_used_seconds: 120,
                created_at: 10,
                updated_at: 20,
            }),
        );
        assert_eq!(
            reduce(&mut state, Action::SetGoalStatus(ThreadGoalStatus::Paused)),
            [Effect::SetGoal {
                task_id: "t1".to_owned(),
                objective: None,
                status: Some(ThreadGoalStatus::Paused),
                token_budget: None,
            }]
        );
        reduce(
            &mut state,
            Action::GoalUpdated(ThreadGoal {
                task_id: "t1".to_owned(),
                objective: "Reach native parity".to_owned(),
                status: ThreadGoalStatus::Paused,
                tokens_used: 1_000,
                token_budget: Some(50_000),
                time_used_seconds: 120,
                created_at: 10,
                updated_at: 30,
            }),
        );
        assert_eq!(
            reduce(&mut state, Action::ClearGoal),
            [Effect::ClearGoal {
                task_id: "t1".to_owned(),
            }]
        );

        reduce(
            &mut state,
            Action::GoalCleared {
                task_id: "t1".to_owned(),
            },
        );
        assert!(
            state
                .goals
                .get("t1")
                .is_some_and(|goal| goal.goal.is_none() && goal.status == LoadStatus::Ready)
        );
        assert!(
            reduce(
                &mut state,
                Action::SetGoal {
                    objective: "invalid budget".to_owned(),
                    token_budget: Some(Some(0)),
                }
            )
            .is_empty()
        );
    }

    #[test]
    fn completed_goal_is_cleared_once_and_stays_attributed_to_its_final_response() {
        let mut state = AppState::default();
        reduce(&mut state, Action::TaskCreated(task("t1")));
        reduce(
            &mut state,
            Action::UpsertTimelineItem {
                task_id: "t1".to_owned(),
                item: TimelineItem {
                    id: "answer-1".to_owned(),
                    turn_id: "turn-7".to_owned(),
                    kind: TimelineKind::Agent,
                    text: "The goal is complete.".to_owned(),
                    detail: None,
                    process_id: None,
                    memory_citations: Vec::new(),
                    sources: Vec::new(),
                    attachments: Vec::new(),
                    output_artifacts: Vec::new(),
                    edit_supported: false,
                    completed: true,
                },
            },
        );
        let completed = ThreadGoal {
            task_id: "t1".to_owned(),
            objective: "Reach native parity".to_owned(),
            status: ThreadGoalStatus::Complete,
            tokens_used: 4_000,
            token_budget: Some(50_000),
            time_used_seconds: 180,
            created_at: 10,
            updated_at: 40,
        };

        assert_eq!(
            reduce(&mut state, Action::GoalUpdated(completed.clone())),
            [Effect::ClearGoal {
                task_id: "t1".to_owned(),
            }]
        );
        let Some(goal_state) = state.goals.get("t1") else {
            panic!("goal state");
        };
        assert_eq!(goal_state.goal.as_ref(), Some(&completed));
        assert_eq!(goal_state.completed_goal.as_ref(), Some(&completed));
        assert_eq!(goal_state.completed_goal_turn_id.as_deref(), Some("turn-7"));
        assert!(
            reduce(&mut state, Action::GoalUpdated(completed.clone())).is_empty(),
            "duplicate completion must not clear twice"
        );

        reduce(
            &mut state,
            Action::GoalCleared {
                task_id: "t1".to_owned(),
            },
        );
        let Some(goal_state) = state.goals.get("t1") else {
            panic!("goal state");
        };
        assert!(goal_state.goal.is_none());
        assert_eq!(goal_state.completed_goal.as_ref(), Some(&completed));
        assert!(
            reduce(&mut state, Action::GoalUpdated(completed.clone())).is_empty(),
            "a late duplicate must not revive a cleared completed goal"
        );
        assert!(
            state
                .goals
                .get("t1")
                .is_some_and(|goal| goal.goal.is_none())
        );

        let mut replacement = completed;
        replacement.status = ThreadGoalStatus::Active;
        replacement.updated_at = 41;
        reduce(&mut state, Action::GoalUpdated(replacement));
        let Some(goal_state) = state.goals.get("t1") else {
            panic!("goal state");
        };
        assert!(goal_state.completed_goal.is_none());
        assert!(goal_state.completed_goal_turn_id.is_none());
    }

