        assert_eq!(state.last_side_panel, InspectorPane::Changes);

        state.route = MainRoute::Settings;
        assert!(reduce(&mut state, Action::ToggleReviewTab).is_empty());
        assert_eq!(state.inspector, InspectorPane::Hidden);
