    #[test]
    fn git_diff_selection_keeps_staged_and_unstaged_requests_separate() {
        let mut state = AppState::default();
        state.git.repository_root = Some(PathBuf::from("C:\\repo"));
        let path = PathBuf::from("src\\lib.rs");

        assert_eq!(
            reduce(
                &mut state,
                Action::SelectDiffPath {
                    path: path.clone(),
                    scope: GitDiffScope::Staged,
                },
            ),
            [Effect::LoadDiff {
                generation: 1,
                root: PathBuf::from("C:\\repo"),
                path: path.clone(),
                staged: true,
            }]
        );
        assert_eq!(state.git.selected_scope, GitDiffScope::Staged);
        assert_eq!(state.git.selected_path.as_ref(), Some(&path));

        reduce(
            &mut state,
            Action::DiffLoaded {
                generation: 1,
                text: "staged patch".to_owned(),
                truncated: false,
            },
        );
        reduce(
            &mut state,
            Action::SelectGitDiffScope(GitDiffScope::Unstaged),
        );

        assert_eq!(state.git.selected_scope, GitDiffScope::Unstaged);
        assert!(state.git.selected_path.is_none());
        assert!(state.git.unified_diff.is_empty());
        assert_eq!(state.git.diff_generation, 2);
        assert_eq!(
            reduce(&mut state, Action::StageAll),
            [Effect::StageAll {
                root: PathBuf::from("C:\\repo"),
            }]
        );
        assert_eq!(
            reduce(&mut state, Action::UnstageAll),
            [Effect::UnstageAll {
                root: PathBuf::from("C:\\repo"),
            }]
        );
    }

    #[test]
    fn late_git_diff_from_a_previous_workspace_is_ignored() {
        let first_root = PathBuf::from("C:\\repo-a");
        let second_root = PathBuf::from("C:\\repo-b");
        let first_path = PathBuf::from("src\\first.rs");
        let second_path = PathBuf::from("src\\second.rs");
        let mut first = task_in_repository("first");
        first.cwd = first_root.clone();
        let mut second = task_in_repository("second");
        second.cwd = second_root.clone();
        let mut state = AppState {
            tasks: vec![first, second],
            selected_task_id: Some("first".to_owned()),
            git: GitState {
                repository_root: Some(first_root.clone()),
                ..GitState::default()
            },
            ..AppState::default()
        };

        assert_eq!(
            reduce(
                &mut state,
                Action::SelectDiffPath {
                    path: first_path,
                    scope: GitDiffScope::Unstaged,
                },
            ),
            [Effect::LoadDiff {
                generation: 1,
                root: first_root,
                path: PathBuf::from("src\\first.rs"),
                staged: false,
            }]
        );

        reduce(&mut state, Action::SelectTask("second".to_owned()));
        let refresh_generation = state.git.refresh_generation;
        reduce(
            &mut state,
            Action::GitSnapshotLoaded {
                generation: refresh_generation,
                git: Box::new(GitState {
                    repository_root: Some(second_root.clone()),
                    files: vec![super::GitFileState {
                        path: second_path.clone(),
                        old_path: None,
                        kind: super::GitFileKind::Modified,
                        staged: false,
                        unstaged: true,
                        staged_additions: 0,
                        staged_deletions: 0,
                        unstaged_additions: 1,
                        unstaged_deletions: 0,
                    }],
                    ..GitState::default()
                }),
                error: None,
            },
        );

        assert_eq!(state.git.diff_generation, 3);
        assert_eq!(
            reduce(
                &mut state,
                Action::SelectDiffPath {
                    path: second_path,
                    scope: GitDiffScope::Unstaged,
                },
            ),
            [Effect::LoadDiff {
                generation: 4,
                root: second_root,
                path: PathBuf::from("src\\second.rs"),
                staged: false,
            }]
        );

        reduce(
            &mut state,
            Action::DiffLoaded {
                generation: 1,
                text: "stale workspace diff".to_owned(),
                truncated: false,
            },
        );

        assert_eq!(state.git.diff_status, Some(LoadStatus::Loading));
        assert!(state.git.unified_diff.is_empty());
    }

