    #[test]
    fn selected_file_diff_failure_is_not_reported_as_empty_success() {
        let mut state = AppState::default();
        state.git.repository_root = Some(repository_path());
        let path = PathBuf::from("src/lib.rs");
        reduce(
            &mut state,
            Action::SelectDiffPath {
                path: path.clone(),
                scope: GitDiffScope::Unstaged,
            },
        );

        reduce(
            &mut state,
            Action::DiffFailed {
                generation: 0,
                message: "stale failure".to_owned(),
            },
        );
        assert_eq!(state.git.diff_status, Some(LoadStatus::Loading));
        assert!(state.git.diff_error.is_none());

        reduce(
            &mut state,
            Action::DiffFailed {
                generation: 1,
                message: "failed to load diff".to_owned(),
            },
        );
        assert_eq!(state.git.selected_path.as_ref(), Some(&path));
        assert_eq!(state.git.diff_status, Some(LoadStatus::Failed));
        assert_eq!(state.git.diff_error.as_deref(), Some("failed to load diff"));
        assert!(state.git.unified_diff.is_empty());
        assert!(!state.git.diff_truncated);
    }

    #[test]
    fn review_sources_use_latest_bounded_diffs_and_fall_back_from_removed_commits() {
        let root = PathBuf::from("C:\\repo");
        let mut state = AppState::default();
        state.git.repository_root = Some(root.clone());

        assert_eq!(
            reduce(&mut state, Action::SelectGitDiffScope(GitDiffScope::Branch)),
            [Effect::LoadBranchDiff {
                generation: 1,
                cwd: root.clone(),
                base: None,
            }]
        );
        assert_eq!(state.git.diff_status, Some(LoadStatus::Loading));

        reduce(
            &mut state,
            Action::BranchDiffLoaded {
                generation: 0,
                base_sha: "stale".to_owned(),
                text: "stale diff".to_owned(),
                truncated: false,
            },
        );
        assert!(state.git.unified_diff.is_empty());

        reduce(
            &mut state,
            Action::BranchDiffLoaded {
                generation: 1,
                base_sha: "a".repeat(MAX_GIT_SHA_BYTES + 1),
                text: "x".repeat(MAX_GIT_DIFF_BYTES + 1),
                truncated: false,
            },
        );
        assert_eq!(state.git.diff_status, Some(LoadStatus::Ready));
        assert_eq!(state.git.unified_diff.len(), MAX_GIT_DIFF_BYTES);
        assert_eq!(
            state.git.diff_base_sha.as_ref().map(String::len),
            Some(MAX_GIT_SHA_BYTES)
        );
        assert!(state.git.diff_truncated);

        let refreshed = GitState {
            repository_root: Some(root.clone()),
            ..GitState::default()
        };
        let refresh_generation = state.git.refresh_generation;
        assert_eq!(
            reduce(
                &mut state,
                Action::GitSnapshotLoaded {
                    generation: refresh_generation,
                    git: Box::new(refreshed),
                    error: None,
                },
            ),
            [Effect::LoadBranchDiff {
                generation: 2,
                cwd: root,
                base: None,
            }]
        );
        assert_eq!(state.git.selected_scope, GitDiffScope::Branch);
        assert_eq!(state.git.diff_status, Some(LoadStatus::Loading));
        assert!(state.git.unified_diff.is_empty());

        assert_eq!(
            reduce(
                &mut state,
                Action::SelectGitDiffScope(GitDiffScope::Uncommitted)
            ),
            [Effect::LoadUncommittedDiff {
                generation: 3,
                root: PathBuf::from("C:\\repo"),
            }]
        );
        reduce(
            &mut state,
            Action::GitSourceDiffLoaded {
                generation: 3,
                scope: GitDiffScope::Uncommitted,
                text: "working tree patch".to_owned(),
                truncated: false,
            },
        );
        assert_eq!(state.git.unified_diff, "working tree patch");

        let commit_sha = "b".repeat(40);
        state.git.commits = vec![GitReviewCommitState {
            sha: commit_sha.clone(),
            subject: "Native review source".to_owned(),
            message: "Native review source".to_owned(),
            committed_at: 1,
        }];
        assert_eq!(
            reduce(
                &mut state,
                Action::SelectGitReviewCommit(commit_sha.clone())
            ),
            [Effect::LoadCommitDiff {
                generation: 4,
                root: PathBuf::from("C:\\repo"),
                sha: commit_sha,
            }]
        );
        assert_eq!(state.git.selected_scope, GitDiffScope::Committed);

        let refreshed = GitState {
            repository_root: Some(PathBuf::from("C:\\repo")),
            ..GitState::default()
        };
        let refresh_generation = state.git.refresh_generation;
        assert_eq!(
            reduce(
                &mut state,
                Action::GitSnapshotLoaded {
                    generation: refresh_generation,
                    git: Box::new(refreshed),
                    error: None,
                },
            ),
            [Effect::LoadBranchDiff {
                generation: 5,
                cwd: PathBuf::from("C:\\repo"),
                base: None,
            }]
        );
        assert_eq!(state.git.selected_scope, GitDiffScope::Branch);
        assert!(state.git.selected_commit_sha.is_none());
    }

