    #[test]
    fn review_start_is_single_flight_and_enforces_start_gates() {
        let mut state = AppState {
            connection: ConnectionStatus::Online,
            ..AppState::default()
        };
        reduce(
            &mut state,
            Action::TaskCreated(task_in_repository("source")),
        );
        let start = || Action::StartReview {
            target: ReviewTarget::UncommittedChanges,
            delivery: ReviewDelivery::Inline,
        };

        assert!(reduce(&mut state, start()).is_empty());
        state.git.repository_root = Some(repository_path());
        state.git_preferences.review_mode = GitReviewMode::LastTurnOnly;
        assert!(reduce(&mut state, start()).is_empty());
        state.git_preferences.review_mode = GitReviewMode::Full;
        state.composer = "draft".to_owned();
        assert!(reduce(&mut state, start()).is_empty());
        state.composer.clear();
        state.composer_attachments.push(ComposerAttachment {
            path: PathBuf::from("note.txt"),
            name: "note.txt".to_owned(),
            kind: ComposerAttachmentKind::Mention,
        });
        assert!(reduce(&mut state, start()).is_empty());
        state.composer_attachments.clear();
        assert!(
            reduce(
                &mut state,
                Action::StartReview {
                    target: ReviewTarget::BaseBranch {
                        branch: " ".to_owned(),
                    },
                    delivery: ReviewDelivery::Inline,
                },
            )
            .is_empty()
        );
        assert!(
            reduce(
                &mut state,
                Action::StartReview {
                    target: ReviewTarget::BaseBranch {
                        branch: "x".repeat(MAX_GIT_BRANCH_BYTES + 1),
                    },
                    delivery: ReviewDelivery::Inline,
                },
            )
            .is_empty()
        );
        state
            .timelines
            .entry("source".to_owned())
            .or_default()
            .active_turn_id = Some("active".to_owned());
        assert!(reduce(&mut state, start()).is_empty());
        state
            .timelines
            .entry("source".to_owned())
            .or_default()
            .active_turn_id = None;

        assert!(!reduce(&mut state, start()).is_empty());
        assert!(reduce(&mut state, start()).is_empty());
        assert_eq!(state.review_start.generation, 1);
        reduce(
            &mut state,
            Action::ComposerChanged("keep this draft".to_owned()),
        );
        assert!(reduce(&mut state, Action::SubmitComposer).is_empty());
        assert_eq!(state.composer, "keep this draft");
    }

    #[test]
    fn review_start_ignores_stale_results_and_scopes_failures_to_the_source() {
        let mut state = AppState {
            connection: ConnectionStatus::Online,
            ..AppState::default()
        };
        reduce(
            &mut state,
            Action::TaskCreated(task_in_repository("source")),
        );
        state.git.repository_root = Some(repository_path());
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Inline,
            },
        );

        reduce(
            &mut state,
            Action::ReviewStartFailed {
                generation: 1,
                source_task_id: "source".to_owned(),
                message: "first failure".to_owned(),
            },
        );
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Inline,
            },
        );
        assert!(
            reduce(
                &mut state,
                Action::ReviewStarted {
                    generation: 1,
                    source_task_id: "source".to_owned(),
                    review_thread_id: "source".to_owned(),
                    turn_id: "late-first".to_owned(),
                    turn_active: true,
                    review_task: None,
                },
            )
            .is_empty()
        );
        assert!(
            reduce(
                &mut state,
                Action::ReviewStartFailed {
                    generation: 1,
                    source_task_id: "source".to_owned(),
                    message: "late-first failure".to_owned(),
                },
            )
            .is_empty()
        );
        assert_eq!(
            state
                .review_start
                .pending
                .as_ref()
                .map(|pending| pending.generation),
            Some(2)
        );
        reduce(
            &mut state,
            Action::ReviewStartFailed {
                generation: 2,
                source_task_id: "source".to_owned(),
                message: "x".repeat(MAX_REVIEW_START_ERROR_BYTES + 1),
            },
        );
        assert_eq!(
            state.review_start.error,
            Some(ReviewStartError {
                source_task_id: "source".to_owned(),
                message: "x".repeat(MAX_REVIEW_START_ERROR_BYTES),
            })
        );

        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Inline,
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "source".to_owned(),
                turn_id: "reused-after-reconnect".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert!(!state.review_start.terminal_events.is_empty());
        reduce(&mut state, Action::ConnectionLost);
        assert!(state.review_start.pending.is_none());
        assert!(state.review_start.terminal_events.is_empty());
        state.connection = ConnectionStatus::Online;
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Inline,
            },
        );
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 4,
                source_task_id: "source".to_owned(),
                review_thread_id: "source".to_owned(),
                turn_id: "reused-after-reconnect".to_owned(),
                turn_active: true,
                review_task: None,
            },
        );
        assert_eq!(
            state.timelines["source"].active_review_turn_id.as_deref(),
            Some("reused-after-reconnect")
        );
    }

    #[test]
    fn review_start_preserves_inline_focus_and_selects_only_available_detached_reviews() {
        let mut state = AppState {
            connection: ConnectionStatus::Online,
            ..AppState::default()
        };
        reduce(
            &mut state,
            Action::TaskCreated(task_in_repository("source")),
        );
        reduce(&mut state, Action::TaskCreated(task_in_repository("other")));
        reduce(&mut state, Action::SelectTask("source".to_owned()));
        state.git.repository_root = Some(repository_path());

        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Inline,
            },
        );
        reduce(&mut state, Action::SelectTask("other".to_owned()));
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "source".to_owned(),
                turn_id: "inline-terminal".to_owned(),
                completed: true,
                failed: false,
            },
        );
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 1,
                source_task_id: "source".to_owned(),
                review_thread_id: "source".to_owned(),
                turn_id: "inline-terminal".to_owned(),
                turn_active: true,
                review_task: None,
            },
        );
        assert_eq!(state.selected_task_id.as_deref(), Some("other"));
        assert!(state.timelines["source"].active_turn_id.is_none());
        assert!(state.timelines["source"].active_review_turn_id.is_none());
        reduce(&mut state, Action::SelectTask("source".to_owned()));
        state.git.repository_root = Some(repository_path());
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Inline,
            },
        );
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 2,
                source_task_id: "source".to_owned(),
                review_thread_id: "source".to_owned(),
                turn_id: "inline".to_owned(),
                turn_active: true,
                review_task: None,
            },
        );
        reduce(&mut state, Action::ComposerChanged("steer".to_owned()));
        assert!(reduce(&mut state, Action::SubmitComposer).is_empty());
        assert_eq!(state.composer, "steer");
        reduce(&mut state, Action::ComposerChanged(String::new()));
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "source".to_owned(),
                turn_id: "inline".to_owned(),
                completed: true,
                failed: false,
            },
        );
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Detached,
            },
        );
        let review = task_in_repository("review-before-turn-started");
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 3,
                source_task_id: "source".to_owned(),
                review_thread_id: review.id.clone(),
                turn_id: "detached".to_owned(),
                turn_active: true,
                review_task: Some(review.clone()),
            },
        );
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: review.id.clone(),
                turn_id: "detached".to_owned(),
            },
        );
        assert_eq!(state.selected_task_id.as_deref(), Some(review.id.as_str()));
        assert!(state.tasks.iter().any(|task| task.id == review.id));

        reduce(&mut state, Action::SelectTask("source".to_owned()));
        state.git.repository_root = Some(repository_path());
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Detached,
            },
        );
        reduce(
            &mut state,
            Action::TurnStarted {
                task_id: "review-before-response".to_owned(),
                turn_id: "detached-two".to_owned(),
            },
        );
        let review = task_in_repository("review-before-response");
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 4,
                source_task_id: "source".to_owned(),
                review_thread_id: review.id.clone(),
                turn_id: "detached-two".to_owned(),
                turn_active: true,
                review_task: Some(review.clone()),
            },
        );
        assert_eq!(state.selected_task_id.as_deref(), Some(review.id.as_str()));
        assert_eq!(
            state.timelines[&review.id].active_review_turn_id.as_deref(),
            Some("detached-two")
        );

        reduce(&mut state, Action::SelectTask("source".to_owned()));
        state.git.repository_root = Some(repository_path());
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Detached,
            },
        );
        let effects = reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 5,
                source_task_id: "source".to_owned(),
                review_thread_id: "unloaded-review".to_owned(),
                turn_id: "detached-three".to_owned(),
                turn_active: true,
                review_task: None,
            },
        );
        assert_eq!(state.selected_task_id.as_deref(), Some("source"));
        assert!(!state.tasks.iter().any(|task| task.id == "unloaded-review"));
        assert!(matches!(effects.as_slice(), [Effect::LoadTasks { .. }]));
        assert!(state.review_start.unresolved_detached.is_some());
        assert!(
            reduce(
                &mut state,
                Action::StartReview {
                    target: ReviewTarget::UncommittedChanges,
                    delivery: ReviewDelivery::Detached,
                },
            )
            .is_empty()
        );
        let unloaded = task_in_repository("unloaded-review");
        let task_generation = state.task_generation;
        reduce(
            &mut state,
            Action::TasksLoaded {
                generation: task_generation,
                tasks: vec![
                    task_in_repository("source"),
                    task_in_repository("other"),
                    unloaded,
                ],
                next_cursor: None,
                append: false,
            },
        );
        assert!(state.review_start.unresolved_detached.is_none());
        assert!(state.review_start.error.is_none());
        assert_eq!(state.selected_task_id.as_deref(), Some("unloaded-review"));

        reduce(&mut state, Action::SelectTask("source".to_owned()));
        state.git.repository_root = Some(repository_path());
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Detached,
            },
        );
        reduce(&mut state, Action::SelectTask("other".to_owned()));
        let review = task_in_repository("review-after-focus-change");
        let review_id = review.id.clone();
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 6,
                source_task_id: "source".to_owned(),
                review_thread_id: review_id.clone(),
                turn_id: "detached-four".to_owned(),
                turn_active: false,
                review_task: Some(review),
            },
        );
        assert_eq!(state.selected_task_id.as_deref(), Some("other"));
        assert!(!state.timelines.contains_key(&review_id));

        reduce(&mut state, Action::SelectTask("source".to_owned()));
        state.git.repository_root = Some(repository_path());
        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Detached,
            },
        );
        reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 7,
                source_task_id: "source".to_owned(),
                review_thread_id: "unloaded-terminal-review".to_owned(),
                turn_id: "detached-terminal".to_owned(),
                turn_active: true,
                review_task: None,
            },
        );
        assert!(state.review_start.unresolved_detached.is_some());
        assert!(state.review_start.error.is_some());
        reduce(
            &mut state,
            Action::TurnInterrupted {
                task_id: "unloaded-terminal-review".to_owned(),
                turn_id: "detached-terminal".to_owned(),
            },
        );
        assert!(state.review_start.unresolved_detached.is_none());
        assert!(state.review_start.error.is_none());

        reduce(
            &mut state,
            Action::StartReview {
                target: ReviewTarget::UncommittedChanges,
                delivery: ReviewDelivery::Detached,
            },
        );
        reduce(
            &mut state,
            Action::TurnCompleted {
                task_id: "terminal-before-detached-response".to_owned(),
                turn_id: "detached-terminal-before-response".to_owned(),
                completed: true,
                failed: false,
            },
        );
        assert_eq!(state.status_message, None);
        let effects = reduce(
            &mut state,
            Action::ReviewStarted {
                generation: 8,
                source_task_id: "source".to_owned(),
                review_thread_id: "terminal-before-detached-response".to_owned(),
                turn_id: "detached-terminal-before-response".to_owned(),
                turn_active: true,
                review_task: None,
            },
        );
        assert!(matches!(effects.as_slice(), [Effect::LoadTasks { .. }]));
        assert!(state.review_start.unresolved_detached.is_none());
        assert!(state.review_start.error.is_none());
    }

    #[test]
    fn git_commit_tracks_generation_and_selected_change_scope() {
        let mut state = AppState::default();
        state.git.repository_root = Some(PathBuf::from("C:\\repo"));
        state.git.branch = Some("feature/native-ui".to_owned());
        state.git.changed_files = 2;
        state.git.staged_files = 1;

        assert_eq!(
            reduce(
                &mut state,
                Action::CommitGit {
                    message: String::new(),
                    include_unstaged: true,
                    next_step: GitCommitNextStep::CommitAndPush,
                },
            ),
            [Effect::CommitGit {
                generation: 1,
                root: PathBuf::from("C:\\repo"),
                branch: Some("feature/native-ui".to_owned()),
                message: String::new(),
                include_unstaged: true,
                next_step: GitCommitNextStep::CommitAndPush,
                force_push: false,
                commit_instructions: String::new(),
            }]
        );
        assert_eq!(
            state.git.pending_commit,
            Some(GitCommitPhase::GeneratingMessage)
        );

        reduce(
            &mut state,
            Action::GitCommitMessageGenerated { generation: 1 },
        );
        assert_eq!(state.git.pending_commit, Some(GitCommitPhase::Committing));
        reduce(&mut state, Action::GitPushStarted { generation: 1 });
        assert_eq!(state.git.pending_commit, Some(GitCommitPhase::Pushing));
        reduce(
            &mut state,
            Action::GitCommitCompleted {
                generation: 1,
                branch: Some("feature/native-ui".to_owned()),
                pushed: true,
            },
        );
        assert!(state.git.pending_commit.is_none());
        assert_eq!(
            state.status_message.as_deref(),
            Some("Pushed feature/native-ui")
        );

        assert_eq!(
            reduce(&mut state, Action::SetGitIncludeUnstaged(false)),
            [Effect::PersistGitIncludeUnstaged(false)]
        );
        state.git.staged_files = 0;
        assert!(
            reduce(
                &mut state,
                Action::CommitGit {
                    message: "Commit staged changes".to_owned(),
                    include_unstaged: false,
                    next_step: GitCommitNextStep::Commit,
                },
            )
            .is_empty()
        );
        assert_eq!(
            state.git.commit_error.as_deref(),
            Some("No staged changes to commit.")
        );

        state.git.ahead = 1;
        assert_eq!(
            reduce(
                &mut state,
                Action::CommitGit {
                    message: String::new(),
                    include_unstaged: false,
                    next_step: GitCommitNextStep::Push,
                },
            ),
            [Effect::CommitGit {
                generation: 2,
                root: PathBuf::from("C:\\repo"),
                branch: Some("feature/native-ui".to_owned()),
                message: String::new(),
                include_unstaged: false,
                next_step: GitCommitNextStep::Push,
                force_push: false,
                commit_instructions: String::new(),
            }]
        );
        assert_eq!(state.git.pending_commit, Some(GitCommitPhase::Pushing));
    }

    #[test]
    fn git_pull_request_status_and_commit_push_workflow_are_branch_scoped() {
        let mut state = AppState {
            connection: ConnectionStatus::Online,
            ..AppState::default()
        };
        let git = GitState {
            repository_root: Some(PathBuf::from("C:\\repo")),
            branch: Some("feature/native-pr".to_owned()),
            default_branch: Some("main".to_owned()),
            changed_files: 2,
            ..GitState::default()
        };
        let refresh_generation = state.git.refresh_generation;
        assert_eq!(
            reduce(
                &mut state,
                Action::GitSnapshotLoaded {
                    generation: refresh_generation,
                    git: Box::new(git),
                    error: None,
                },
            ),
            [Effect::LoadGitPullRequest {
                root: PathBuf::from("C:\\repo"),
                branch: "feature/native-pr".to_owned(),
            }]
        );
        assert_eq!(
            state.git.pull_request_provider,
            GitPullRequestProvider::Loading
        );
        reduce(
            &mut state,
            Action::GitPullRequestStatusLoaded {
                branch: "feature/native-pr".to_owned(),
                provider: GitPullRequestProvider::Available,
                pull_request: None,
            },
        );

        assert_eq!(
            reduce(
                &mut state,
                Action::CreateGitPullRequest {
                    title: String::new(),
                    body: String::new(),
                    include_local_changes: true,
                    is_draft: true,
                    open_in_browser: false,
                },
            ),
            [Effect::CreateGitPullRequest {
                generation: 2,
                root: PathBuf::from("C:\\repo"),
                branch: "feature/native-pr".to_owned(),
                base_branch: "main".to_owned(),
                title: String::new(),
                body: String::new(),
                include_local_changes: true,
                next_step: GitPullRequestNextStep::CommitPushAndCreate,
                is_draft: true,
                open_in_browser: false,
                force_push: false,
                commit_instructions: String::new(),
                pull_request_instructions: String::new(),
            }]
        );
        assert_eq!(
            state.git.pending_pull_request,
            Some(GitPullRequestPhase::GeneratingMessages)
        );
        reduce(
            &mut state,
            Action::GitPullRequestCommitStarted { generation: 2 },
        );
        assert_eq!(
            state.git.pending_pull_request,
            Some(GitPullRequestPhase::Committing)
        );
        reduce(
            &mut state,
            Action::GitPullRequestPushStarted { generation: 2 },
        );
        assert_eq!(
            state.git.pending_pull_request,
            Some(GitPullRequestPhase::Pushing)
        );
        reduce(
            &mut state,
            Action::GitPullRequestCreateStarted { generation: 2 },
        );
        assert_eq!(
            state.git.pending_pull_request,
            Some(GitPullRequestPhase::Creating)
        );
        reduce(
            &mut state,
            Action::GitPullRequestCompleted {
                generation: 2,
                pull_request: GitPullRequestState {
                    number: Some(42),
                    title: "Add native PR flow".to_owned(),
                    url: "https://github.com/Kiwunaka/codexRS/pull/42".to_owned(),
                    base_branch: "main".to_owned(),
                    head_branch: "feature/native-pr".to_owned(),
                    is_draft: true,
                },
                open_in_browser: false,
            },
        );
        assert!(state.git.pending_pull_request.is_none());
        assert_eq!(
            state.status_message.as_deref(),
            Some("Created PR for feature/native-pr")
        );
        assert_eq!(
            state
                .git
                .pull_request
                .as_ref()
                .and_then(|pull_request| pull_request.number),
            Some(42)
        );
    }

