    #[test]
    fn account_usage_refresh_is_single_effect_and_bounds_provider_fields() {
        let mut state = AppState::default();

        assert_eq!(
            reduce(&mut state, Action::RefreshAccount),
            [Effect::LoadAccount]
        );
        assert_eq!(state.account.status, LoadStatus::Loading);

        reduce(
            &mut state,
            Action::AccountLoaded {
                profile: Some(AccountProfile {
                    kind: AccountKind::ChatGpt,
                    email: Some(format!("{}@example.com", "a".repeat(600))),
                    plan: Some(" plus ".to_owned()),
                    uses_codex_managed_credentials: None,
                }),
                requires_openai_auth: true,
                usage_limits: vec![
                    UsageLimitWindow {
                        used_percent: 25,
                        window_duration_mins: Some(300),
                        resets_at: Some(1_900_000_000),
                    },
                    UsageLimitWindow {
                        used_percent: 50,
                        window_duration_mins: Some(10_080),
                        resets_at: None,
                    },
                    UsageLimitWindow {
                        used_percent: 75,
                        window_duration_mins: Some(43_200),
                        resets_at: None,
                    },
                ],
                credits: Some(AccountCredits {
                    has_credits: true,
                    unlimited: false,
                    balance: Some(format!("  {}  ", "9".repeat(600))),
                }),
                rate_limit_reset_credits_available: Some(2),
                usage_error: None,
                token_activity: Some(AccountTokenActivitySummary {
                    lifetime_tokens: Some(1_250_000),
                    peak_daily_tokens: Some(250_000),
                    longest_running_turn_sec: Some(5_400),
                    current_streak_days: Some(7),
                    longest_streak_days: Some(21),
                    daily_usage_buckets: (0..MAX_ACCOUNT_DAILY_USAGE_BUCKETS + 1)
                        .map(|tokens| AccountDailyUsageBucket {
                            start_date: "2026-07-01".to_owned(),
                            tokens: i64::try_from(tokens).unwrap_or(i64::MAX),
                        })
                        .collect(),
                }),
                token_activity_error: None,
            },
        );

        assert_eq!(state.account.status, LoadStatus::Ready);
        assert_eq!(state.account.usage_limits.len(), 2);
        assert_eq!(
            state
                .account
                .profile
                .as_ref()
                .and_then(|profile| profile.plan.as_deref()),
            Some("plus")
        );
        assert!(
            state
                .account
                .profile
                .as_ref()
                .and_then(|profile| profile.email.as_ref())
                .is_some_and(|email| email.len() <= 512)
        );
        assert_eq!(state.account.rate_limit_reset_credits_available, Some(2));
        assert!(
            state
                .account
                .credits
                .as_ref()
                .and_then(|credits| credits.balance.as_ref())
                .is_some_and(|balance| balance.len() <= 512)
        );
        assert_eq!(
            state
                .account
                .token_activity
                .as_ref()
                .and_then(|summary| summary.lifetime_tokens),
            Some(1_250_000)
        );
        assert_eq!(
            state
                .account
                .token_activity
                .as_ref()
                .map(|summary| summary.daily_usage_buckets.len()),
            Some(MAX_ACCOUNT_DAILY_USAGE_BUCKETS)
        );
        assert!(
            state
                .account
                .token_activity
                .as_ref()
                .is_some_and(|summary| summary
                    .daily_usage_buckets
                    .iter()
                    .all(|bucket| { bucket.start_date == "2026-07-01" && bucket.tokens >= 0 }))
        );
    }

    #[test]
    fn account_authentication_is_single_flight_and_refreshes_after_completion() {
        let mut state = AppState::default();

        assert_eq!(
            reduce(&mut state, Action::StartAccountLogin),
            [Effect::StartAccountLogin]
        );
        assert!(reduce(&mut state, Action::StartAccountLogin).is_empty());
        reduce(
            &mut state,
            Action::AccountLoginStarted {
                login_id: "login-1".to_owned(),
                authorization_url: "https://auth.openai.com/".to_owned(),
                user_code: None,
            },
        );
        assert_eq!(
            state.account.auth_operation,
            AccountAuthOperation::AwaitingLogin
        );
        assert_eq!(
            reduce(&mut state, Action::CancelAccountLogin),
            [Effect::CancelAccountLogin {
                login_id: "login-1".to_owned(),
            }]
        );
        assert!(reduce(&mut state, Action::CancelAccountLogin).is_empty());
        reduce(
            &mut state,
            Action::AccountLoginCanceled {
                login_id: "login-1".to_owned(),
            },
        );
        assert_eq!(state.account.auth_operation, AccountAuthOperation::Idle);

        reduce(&mut state, Action::StartAccountLogin);
        reduce(
            &mut state,
            Action::AccountLoginStarted {
                login_id: "login-2".to_owned(),
                authorization_url: "https://auth.openai.com/".to_owned(),
                user_code: None,
            },
        );
        assert_eq!(
            reduce(
                &mut state,
                Action::AccountLoginCompleted {
                    login_id: Some("login-2".to_owned()),
                    success: true,
                },
            ),
            [Effect::LoadAccount]
        );
        assert_eq!(state.account.status, LoadStatus::Loading);

        reduce(
            &mut state,
            Action::AccountLoaded {
                profile: Some(AccountProfile {
                    kind: AccountKind::ChatGpt,
                    email: Some("developer@example.com".to_owned()),
                    plan: Some("Plus".to_owned()),
                    uses_codex_managed_credentials: None,
                }),
                requires_openai_auth: true,
                usage_limits: Vec::new(),
                credits: None,
                rate_limit_reset_credits_available: None,
                usage_error: None,
                token_activity: None,
                token_activity_error: None,
            },
        );
        assert_eq!(
            reduce(&mut state, Action::LogoutAccount),
            [Effect::LogoutAccount]
        );
        assert!(reduce(&mut state, Action::LogoutAccount).is_empty());
        assert_eq!(
            reduce(&mut state, Action::AccountLoggedOut),
            [Effect::LoadAccount]
        );
        assert!(state.account.profile.is_none());
    }

