    #[test]
    fn bedrock_restart_failure_reports_a_generic_runtime_error() {
        let mut state = AppState::default();

        reduce(&mut state, Action::StartBedrockLogin);
        reduce(&mut state, Action::AccountBedrockLoginAccepted);
        reduce(&mut state, Action::AccountBedrockRestartFailed);

        assert_eq!(state.account.auth_operation, AccountAuthOperation::Idle);
        assert_eq!(
            state.connection,
            ConnectionStatus::Failed(
                "Could not restart Codex runtime. Please try again.".to_owned()
            )
        );
        assert_eq!(
            state.account.auth_error.as_deref(),
            Some(
                "Amazon Bedrock credentials were saved, but Codex runtime could not restart. Retry the connection."
            )
        );
        assert!(state.status_message.is_none());
    }

    #[test]
    fn device_code_login_is_ephemeral_and_cleared_when_cancelled() {
        let mut state = AppState::default();

        assert_eq!(
            reduce(&mut state, Action::StartAccountDeviceCodeLogin),
            [Effect::StartAccountDeviceCodeLogin]
        );
        assert!(reduce(&mut state, Action::StartAccountLogin).is_empty());
        reduce(
            &mut state,
            Action::AccountLoginStarted {
                login_id: "login-1".to_owned(),
                authorization_url: "https://auth.openai.com/device".to_owned(),
                user_code: Some("ABCD-EFGH".to_owned()),
            },
        );

        assert_eq!(
            state.account.login_verification_url.as_deref(),
            Some("https://auth.openai.com/device")
        );
        assert_eq!(state.account.login_user_code.as_deref(), Some("ABCD-EFGH"));
        assert_eq!(
            reduce(&mut state, Action::CancelAccountLogin),
            [Effect::CancelAccountLogin {
                login_id: "login-1".to_owned(),
            }]
        );
        assert_eq!(
            state.account.login_verification_url.as_deref(),
            Some("https://auth.openai.com/device")
        );
        assert_eq!(state.account.login_user_code.as_deref(), Some("ABCD-EFGH"));
        reduce(
            &mut state,
            Action::AccountLoginCancelFailed("temporary failure".to_owned()),
        );
        assert_eq!(
            state.account.auth_operation,
            AccountAuthOperation::AwaitingLogin
        );
        assert_eq!(
            state.account.login_verification_url.as_deref(),
            Some("https://auth.openai.com/device")
        );
        assert_eq!(state.account.login_user_code.as_deref(), Some("ABCD-EFGH"));
        reduce(
            &mut state,
            Action::AccountLoginCanceled {
                login_id: "login-1".to_owned(),
            },
        );
        assert!(state.account.login_verification_url.is_none());
        assert!(state.account.login_user_code.is_none());
    }

    #[test]
    fn account_login_started_rejects_empty_or_oversize_opaque_values() {
        for (login_id, authorization_url, user_code) in [
            (
                String::new(),
                "https://auth.openai.com/device".to_owned(),
                Some("ABCD-EFGH".to_owned()),
            ),
            (
                "x".repeat(MAX_ACCOUNT_FIELD_BYTES + 1),
                "https://auth.openai.com/device".to_owned(),
                Some("ABCD-EFGH".to_owned()),
            ),
            (
                "login-1".to_owned(),
                String::new(),
                Some("ABCD-EFGH".to_owned()),
            ),
            (
                "login-1".to_owned(),
                "x".repeat(8 * 1024 + 1),
                Some("ABCD-EFGH".to_owned()),
            ),
            (
                "login-1".to_owned(),
                "https://auth.openai.com/device".to_owned(),
                Some(String::new()),
            ),
            (
                "login-1".to_owned(),
                "https://auth.openai.com/device".to_owned(),
                Some("x".repeat(MAX_ACCOUNT_FIELD_BYTES + 1)),
            ),
        ] {
            let mut state = AppState::default();
            reduce(&mut state, Action::StartAccountDeviceCodeLogin);
            assert!(
                reduce(
                    &mut state,
                    Action::AccountLoginStarted {
                        login_id,
                        authorization_url,
                        user_code,
                    },
                )
                .is_empty()
            );
            assert_eq!(state.account.auth_operation, AccountAuthOperation::Idle);
            assert!(state.account.login_id.is_none());
            assert!(state.account.login_verification_url.is_none());
            assert!(state.account.login_user_code.is_none());
        }
    }

    #[test]
    fn feedback_upload_is_validated_bounded_and_single_flight() {
        let mut state = AppState {
            selected_task_id: Some("thread-1".to_owned()),
            ..AppState::default()
        };

        assert!(
            reduce(
                &mut state,
                Action::SubmitFeedback {
                    classification: FeedbackClassification::Bug,
                    reason: "   ".to_owned(),
                    include_logs: true,
                },
            )
            .is_empty()
        );
        assert_eq!(
            state.feedback.error.as_deref(),
            Some("Share details before submitting.")
        );

        assert_eq!(
            reduce(
                &mut state,
                Action::SubmitFeedback {
                    classification: FeedbackClassification::BadResult,
                    reason: "  The result missed the requested file.  ".to_owned(),
                    include_logs: true,
                },
            ),
            [Effect::SubmitFeedback {
                classification: FeedbackClassification::BadResult,
                reason: "The result missed the requested file.".to_owned(),
                include_logs: true,
                thread_id: Some("thread-1".to_owned()),
            }]
        );
        assert!(state.feedback.pending);
        assert!(
            reduce(
                &mut state,
                Action::SubmitFeedback {
                    classification: FeedbackClassification::Other,
                    reason: "second request".to_owned(),
                    include_logs: false,
                },
            )
            .is_empty()
        );

        reduce(
            &mut state,
            Action::FeedbackSubmitted {
                feedback_id: "feedback-1".to_owned(),
            },
        );
        assert!(!state.feedback.pending);
        assert_eq!(state.feedback.feedback_id.as_deref(), Some("feedback-1"));
        assert_eq!(state.status_message.as_deref(), Some("Feedback uploaded"));
    }

